let lang=localStorage.getItem('router-studio-language')||'zh'; if(!words[lang])lang='zh';
const t=k=>words[lang][k]||words.en[k]||k;
let token=new URLSearchParams(location.hash.slice(1)).get('token');
if(token){sessionStorage.setItem('router-studio-token',token);history.replaceState(null,'',location.pathname)}
else token=sessionStorage.getItem('router-studio-token')||'';
const state={view:'overview',base:null,draft:null,meta:null,scenario:'review',options:{environment:'ready',active_children:0,children_started:0},result:null,busy:false,dirty:false,modal:false,connected:true};
let toastTimer,simTimer,simulationSequence=0;
const $=s=>document.querySelector(s);
Object.assign(words.zh,{"economy": "经济方案", "balanced": "稳定方案", "premium": "土豪方案", "routingStrategy": "选模取舍", "profileTitle": "三种取舍，一套验收标准", "profileIntro": "稳定方案默认开启。选择预设会载入整套草稿，确认应用后生效。", "economyDesc": "低风险、精确需求、有测试的局部实现先试 Luna；条件不齐用 Sol。关键任务仍用 Astra。", "balancedDesc": "Sol 负责日常编程，复杂任务提高推理强度；关键任务交给 Astra。推荐大多数人使用。", "premiumDesc": "复杂任务直接 Astra；有具体依据的相邻档位模糊，先升一级。不会自动增加代理数量。", "profileEvidence": "依据：官方模型建议 + 公开用户小样本实测 + 独立评测。预设是工程判断，尚未在你的项目上做模型 A/B 测试。", "profileResearch": "查看用户原始实测", "profileVision": "查看独立视觉评测", "profileQuota": "订阅额度不能按 API 标价折算；经济方案表示选模倾向，不承诺最低总开销。", "chooseProfile": "载入方案", "currentProfile": "当前草稿", "presetText": "按当前草稿的任务条件和选模取舍执行；所有方案都先检查委派是否必要。", "presetsDesc": "预设同步修改模型候选、模糊边界策略与协作限额。经济方案的局部试用复用确定性档候选池。", "defaultDesc": "先判定严格任务分档，再应用当前选模取舍。经济方案允许可验收的局部试用，土豪方案优先处理模糊边界。", "scenarioLocalTrial": "有测试的局部实现", "scenarioLocalTrialDesc": "需求精确、文本输入、低风险且有测试；经济方案允许先试 Luna。", "scenarioBorderline": "常规与复杂之间", "scenarioBorderlineDesc": "局部接口已知，但相邻状态交互仍有具体疑点；土豪方案先升档。", "economy-testable-local-trial": "经济方案：可测试的低风险局部实现先试轻量候选，验收不通过再升级", "premium-ambiguous-boundary-upgrade": "土豪方案：有依据的相邻档位模糊，提升一级", "ruleMechanical": "仅文本提取/转换；规则精确、可机械验证、局部范围、低风险、低不确定性全部成立。"});
Object.assign(words.en,{"economy": "Economy", "balanced": "Balanced", "premium": "Premium", "routingStrategy": "Model trade-off", "profileTitle": "Three trade-offs. One acceptance standard.", "profileIntro": "Balanced is the default. Choose a complete draft, then review and apply.", "economyDesc": "Try Luna for exact, low-risk local implementation with tests; otherwise use Sol. Critical work still uses Astra.", "balancedDesc": "Sol for everyday coding, higher effort for complex work, Astra for critical work. Recommended for most people.", "premiumDesc": "Astra for complex work; promote one lane when adjacent-lane ambiguity has concrete evidence. No extra agents by default.", "profileEvidence": "Basis: official guidance, a small public user test, and independent evaluations. Engineering choices; no model A/B test on your projects yet.", "profileResearch": "Read the original user test", "profileVision": "Read independent vision evals", "profileQuota": "API prices do not translate into subscription quota. Economy is a routing preference, not a guarantee of minimum total usage.", "chooseProfile": "Load preset", "currentProfile": "Current draft", "presetText": "Use the task conditions and model trade-off in this draft. Every preset first checks whether delegation is necessary.", "presetsDesc": "Presets replace routes, boundary behavior and collaboration limits. Economic local trials reuse the deterministic candidate pool.", "defaultDesc": "Apply the strict task rubric, then the selected trade-off. Economy allows a testable local trial; Premium promotes evidenced ambiguous boundaries.", "scenarioLocalTrial": "Testable local implementation", "scenarioLocalTrialDesc": "Exact, text-only, low risk, with tests; Economy allows a Luna trial.", "scenarioBorderline": "Between routine and complex", "scenarioBorderlineDesc": "Known local API but a concrete question about adjacent state interactions; Premium promotes the lane.", "economy-testable-local-trial": "Economy: try lightweight candidates for testable, low-risk local work; acceptance failure triggers recovery", "premium-ambiguous-boundary-upgrade": "Premium: evidenced ambiguity between adjacent lanes promotes one lane", "ruleMechanical": "Text extraction/transformation only: exact rules, deterministic checks, local scope, low consequence and low uncertainty are all required."});
const normalise=p=>({...copy(p),classification_mode:p.classification_mode||'legacy',routing_strategy:p.routing_strategy||'balanced',triggers:{explicit_user:true,verification_gap:true,deadline_parallel:true,...p.triggers}});
const api=async(path,data)=>{
  const res=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'X-Router-Token':token,'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});
  const out=await res.json(); if(!res.ok){const err=new Error(out.error||'Error');err.status=res.status;throw err}return out;
};
function errorText(err){if(err.status===409)return t('conflictError');if(err.status===401)return t('sessionError');if(err.status===400||err.status===413)return t('invalid');return err.status?t('saveFailed'):t('connectError')}
function toast(message){clearTimeout(toastTimer);const node=$('#toast');node.textContent=message;node.classList.add('visible');toastTimer=setTimeout(()=>node.classList.remove('visible'),3800)}
function button(action,label,icon,cls='btn-outline',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${icon?I(icon):''}${E(label)}</button>`}
function sw(key,value,label){return `<button class="switch ${value?'on':''}" role="switch" aria-checked="${value}" aria-label="${E(label)}" data-toggle="${key}"></button>`}
function options(values,current){return values.map(([v,label])=>`<option value="${E(v)}" ${v===String(current)?'selected':''}>${E(label)}</option>`).join('')}
function select(id,values,current,label){return `<select class="select" id="${id}" data-select="${id}" aria-label="${E(label)}">${options(values,current)}</select>`}
function differences(){
  if(!state.base)return[];const a=state.base,b=state.draft,rows=[];
  const bool=v=>t(v?'on':'off');const add=(key,label,fmt=String)=>{if(JSON.stringify(a[key])!==JSON.stringify(b[key]))rows.push({label:t(label),before:fmt(a[key]),after:fmt(b[key])})};
  add('version','policy');add('routing_strategy','routingStrategy',v=>t(v));add('classification_mode','classificationMode',v=>t(v));add('enabled','enabled',bool);add('max_children','maxChildren');add('max_children_per_request','maxTotal');add('minimum_reasoning_minutes','minMinutes');add('max_recovery_attempts','retries');add('catalog_max_age_hours','capabilityAge');
  for(const key of Object.keys(b.triggers))if(a.triggers[key]!==b.triggers[key])rows.push({label:t(key),before:bool(a.triggers[key]),after:bool(b.triggers[key])});
  for(const lane of Object.keys(b.lanes))if(JSON.stringify(a.lanes[lane])!==JSON.stringify(b.lanes[lane]))rows.push({label:t(lane),before:a.lanes[lane].map(([m,f])=>`${shortModel(m)} / ${t(f)}`).join(' → '),after:b.lanes[lane].map(([m,f])=>`${shortModel(m)} / ${t(f)}`).join(' → ')});
  return rows;
}
function shortModel(model){return({'gpt-6-luna':'Luna','gpt-6-sol':'Sol','gpt-6-astra':'Astra','gpt-5.6-sol':'Sol 5.6','gpt-5.6-terra':'Terra'})[model]||model}
function presetName(){const p=state.draft;for(const [key,value] of Object.entries(state.meta.presets||{}))if(Object.keys(normalise(value)).every(k=>JSON.stringify(normalise(value)[k])===JSON.stringify(p[k])))return key;return'custom'}
function flow(){return `<section class="panel"><div class="panel-head"><div><h2>${t('flowTitle')}</h2><p class="panel-desc">${t('flowDesc')}</p></div><span class="switch-label">${t(state.draft.enabled?'enabled':'disabled')}${sw('enabled',state.draft.enabled,t('enabled'))}</span></div><div class="flow ${state.busy?'running':''} ${!state.draft.enabled?'disabled-overlay':''}"><svg class="flow-wires" viewBox="0 0 600 206" preserveAspectRatio="none" aria-hidden="true"><path d="M148 104H238M375 104H405Q421 104 421 84V60H483M421 104V147H483"/><path class="particle" d="M148 104H238M375 104H405Q421 104 421 84V60H483"/></svg><div class="flow-node start">${I('message')}${t('receive')}</div><div class="flow-node gate">${I('branch')}${t('need')}</div><div class="flow-node direct">${I('user')}${t('main')}</div><div class="flow-node delegate">${I('layers')}${t('route')}</div><span class="flow-label top">${t('unneeded')}</span><span class="flow-label bottom">${t('needed')}</span></div><div class="flow-legend"><span>${I('shield')}${t('flowLegend')}</span><span>${t('flowDetail')}</span></div></section>`}
function triggers(){return `<section class="panel"><div class="panel-head"><div><h2>${t('triggersTitle')}</h2><p class="panel-desc">${t('triggersDesc')}</p></div><span class="page-num">01—03</span></div><div class="trigger-grid">${[['explicit_user','message','explicitDesc'],['verification_gap','shield','reviewDesc'],['deadline_parallel','bolt','speedDesc']].map(([key,icon,desc])=>`<div class="trigger-card ${!state.draft.triggers[key]?'off':''}"><div class="trigger-top"><span class="trigger-icon">${I(icon)}</span>${sw('triggers.'+key,state.draft.triggers[key],t(key))}</div><h3>${t(key)}</h3><p>${t(desc)}</p></div>`).join('')}</div></section>`}
function limits(){const p=state.draft;return `<section class="panel"><div class="panel-head"><div><h2>${t('limitsTitle')}</h2><p class="panel-desc">${t('limitsDesc')}</p></div>${I('tune')}</div><div class="limits">${[['max_children','maxChildren','maxChildrenHelp',1,3,1],['max_children_per_request','maxTotal','maxTotalHelp',1,3,1],['minimum_reasoning_minutes','minMinutes','minMinutesHelp',0,30,1],['max_recovery_attempts','retries','retriesHelp',0,1,1],['catalog_max_age_hours','capabilityAge','capabilityHelp',.25,24,.25]].map(([key,label,help,min,max,step])=>`<div class="limit-row"><div><label class="limit-label" for="range-${key}">${t(label)}</label><div class="limit-help">${t(help)}</div></div><input class="range" id="range-${key}" data-range="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${p[key]}" aria-valuetext="${p[key]}"><output class="limit-value" for="range-${key}" data-output="${key}">${p[key]}</output></div>`).join('')}</div></section>`}

function loadRecommended(){if(!state.meta.recommended_policy)return;state.draft=normalise(state.meta.recommended_policy);edited();toast(t('restoredDefault'))}
function defaultBanner(){const strict=state.draft.classification_mode==='evidence-v1';return `<section class="defaults-banner"><div><span class="badge">${E(t(state.draft.classification_mode))}</span><h2>${t('defaultTitle')}</h2><p>${t(strict?'defaultDesc':'legacyNotice')}</p><details><summary>${t('classificationTitle')}</summary><div class="rules-grid">${['mechanical','routine','complex','critical'].map(lane=>`<div><strong>${t(lane)}</strong><p>${t('rule'+lane[0].toUpperCase()+lane.slice(1))}</p></div>`).join('')}</div><p class="rule-caveat">${t('ruleCaveat')}</p></details></div>${button('restore-defaults',t('restoreDefault'),'refresh','btn-outline')}</section>`}

function presetCard(){return `<section class="preset-card"><div class="eyebrow">${t('currentStrategy')}</div><h2>${t(presetName())}</h2><p>${t('presetText')}</p><div class="preset-tags"><span>${t('qualityFirst')}</span><span>${t('bounded')}</span></div>${button('go-lab',t('tryStrategy'),'arrowUp','btn-lime')}</section>`}
function reasonKey(reason){if(reason==='task-assessment-missing')return'reasonAssessment';if(reason==='router-disabled'||reason==='delegation-disabled')return'reasonDisabled';if(reason==='delegation-trigger-disabled')return'reasonTrigger';if(reason==='direct-by-default-no-delegation-need')return'reasonDefault';if(reason==='delegation-benefit-not-established'||reason==='direct-work-has-lower-overhead')return'reasonSmall';if(reason==='total-child-budget-exhausted'||reason==='recovery-budget-exhausted')return'reasonQuota';if(reason==='concurrency-cap'||reason==='file-access-conflict'||reason==='shared-resource-busy')return'reasonBusy';if(reason==='fix-environment-or-capability-without-reasoning-escalation')return'reasonNetwork';if(reason==='no-supported-quality-lane')return'reasonModel';if(reason==='bounded-independent-work-with-supported-route')return'reasonDelegate';return'reasonOther'}
function resultTitle(){if(state.busy)return t('running');if(!state.result)return t('waiting');return t({direct:'directShort',delegate:'delegate',serialize:'serialize',report_unsupported:'unsupported'}[state.result.result.action]||'directShort')}
function resultDetail(){if(!state.result)return t('waitingDesc');const r=state.result.result;return r.action==='delegate'?`${shortModel(r.recommended.model)} · ${t(r.recommended.effort)}`:t(reasonKey(r.reason))}
function quickSim(){return `<section class="panel quick-sim"><div class="section-label">${t('quickTitle')}</div><label class="field-label" for="quick-scenario">${t('scenarioLabel')}</label>${select('quick-scenario',scenarios.map(k=>[k,t('scenario'+scenarioKeys[k])]),state.scenario,t('scenarioLabel'))}<div class="sim-result" aria-live="polite"><div class="result-kicker">${I('branch')}${t('simulation')}</div><div class="result-title">${resultTitle()}</div><div class="result-detail">${E(resultDetail())}</div></div>${button('simulate',t(state.result?'rerun':'simulate'),'play','btn-outline',state.busy?'disabled':'')}<p class="sim-foot">${I('info')}${t('simFoot')}</p></section>`}
function sourcePanel(){return `<section class="panel source-panel">${t('source')}<p>${t('sourceDesc')}</p><code>${E(state.meta.target)}</code></section>`}
function stats(){const p=state.draft;return `<div class="stats">${[['currentMode',`<span class="word">${t('directShort')}</span>`,'user'],['concurrent',`<span data-stat="max_children">${String(p.max_children).padStart(2,'0')}</span><small>${t('agents')}</small>`,'layers'],['totalStarts',`<span data-stat="max_children_per_request">${String(p.max_children_per_request).padStart(2,'0')}</span><small>${t('starts')}</small>`,'branch'],['threshold',`<span data-stat="minimum_reasoning_minutes">${String(p.minimum_reasoning_minutes).padStart(2,'0')}</span><small>${t('minutes')}</small>`,'clock']].map(([label,val,icon],i)=>`<div class="stat"><div><div class="stat-label">${t(label)}</div><div class="stat-value ${i===0?'word':''}">${val}</div></div><span class="stat-icon">${I(icon)}</span></div>`).join('')}</div>`}

function profiles(){return `<section class="profiles-section"><div class="panel-head"><div><h2>${t('profileTitle')}</h2><p class="panel-desc">${t('profileIntro')}</p></div></div><div class="profile-grid">${['economy','balanced','premium'].map((key,i)=>`<article class="profile-choice ${presetName()===key?'selected':''}"><div class="profile-heading"><span class="lane-number">0${i+1}</span><h3>${t(key)}</h3>${presetName()===key?`<span class="badge">${t('currentProfile')}</span>`:''}</div><p>${t(key+'Desc')}</p><div class="profile-routes">${Object.entries(state.meta.presets[key].lanes).map(([lane,pairs])=>`<div><span>${t(lane)}</span><strong>${shortModel(pairs[0][0])} / ${t(pairs[0][1])}</strong></div>`).join('')}<div><span>${t('scenarioLocalTrial')}</span><strong>${key==='economy'?'Luna':'Sol'} / ${t(key==='balanced'?'medium':'high')}</strong></div></div><button class="btn ${key==='balanced'?'btn-primary':'btn-outline'}" data-preset="${key}">${t('chooseProfile')} · ${t(key)}</button></article>`).join('')}</div><p class="profile-evidence">${t('profileEvidence')} <a href="https://community.openai.com/t/announcing-gpt-6-sol-and-gpt-6-luna-in-the-api-codex-and-chatgpt/1399925/6" target="_blank" rel="noopener noreferrer">${t('profileResearch')} ↗</a> · <a href="https://playground.roboflow.com/models/openai/gpt-6-luna" target="_blank" rel="noopener noreferrer">${t('profileVision')} ↗</a></p><p class="rule-caveat">${t('profileQuota')}</p></section>`}

function overview(){return stats()+profiles()+defaultBanner()+`<div class="workspace-grid"><div class="stack">${flow()}${triggers()}${limits()}</div><aside class="stack right-rail">${presetCard()}${quickSim()}${sourcePanel()}</aside></div><div class="footer-note">${I('shield')}${t('guardrail')}</div>`}
function modelView(){return profiles()+defaultBanner()+`<div class="workspace-grid"><div class="lane-list">${Object.entries(state.draft.lanes).map(([lane,pairs],n)=>`<section class="panel lane-card"><div class="lane-heading"><div class="lane-name"><span class="lane-number">0${n+1}</span><div><h2>${t(lane)}</h2><p>${t(lane+'Desc')}</p></div></div><span class="badge neutral">${lane.toUpperCase()}</span></div><div class="lane-rule"><strong>${t('rule'+lane[0].toUpperCase()+lane.slice(1))}</strong><p>${t('example'+lane[0].toUpperCase()+lane.slice(1))}</p></div>${pairs.map(([model,effort],i)=>`<div class="model-row"><span class="model-order">${t(i?'fallback':'first')}${i?` ${i}`:''}</span><input class="model-input" aria-label="${E(t(lane)+' '+t(i?'fallback':'first'))}" data-model="${lane}:${i}" list="model-options" value="${E(model)}"><select class="select" aria-label="${E(t(lane)+' '+t('effort'))}" data-effort="${lane}:${i}">${options(['low','medium','high','xhigh'].map(x=>[x,t(x)]),effort)}</select><div class="model-actions"><button class="icon-button" data-up="${lane}:${i}" aria-label="${t('moveUp')}" ${i===0?'disabled':''}>${I('up')}</button><button class="icon-button" data-remove="${lane}:${i}" aria-label="${t('removeCandidate')}" ${pairs.length===1?'disabled':''}>${I('close')}</button></div></div>`).join('')}<button class="add-fallback" data-add="${lane}" ${pairs.length>=4?'disabled':''}>${I('plus')}${t('addCandidate')}</button></section>`).join('')}</div><aside class="stack right-rail"><section class="panel info-panel"><h3>${I('layers')}${t('modelNoteTitle')}</h3><p>${t('modelNote')}</p><p>${t('modelNote2')}</p></section>${quickSim()}<section class="panel info-panel"><h3>${I('leaf')}${t('presetsTitle')}</h3><p>${t('presetsDesc')}</p><div class="presets">${['economy','balanced','premium'].map(k=>`<button class="preset-btn" data-preset="${k}">${t(k)}</button>`).join('')}</div></section></aside></div><datalist id="model-options">${state.meta.models.map(m=>`<option value="${m}">`).join('')}</datalist>`}
function trace(){const r=state.result?.result;const action=r?.action;const early=!r||['router-disabled','delegation-disabled','direct-by-default-no-delegation-need','delegation-trigger-disabled'].includes(r.reason);const reachedModel=r&&!!r.lane;return `<section class="panel trace-card ${state.busy?'simulation-running':''}"><div class="trace-top"><span>${t('traceTitle')}</span><span class="badge">${t('realEngine')}</span></div><div class="trace-status"><div class="result-circle">${I(action==='delegate'?'branch':action==='serialize'?'clock':'check')}</div><div><h2>${resultTitle()}</h2><p>${E(resultDetail())}</p></div></div>${r?.classification?`<div class="classification-proof"><strong>${t('classificationTitle')} · ${t(r.lane)}</strong><ul>${r.classification.reasons.map(code=>`<li>${E(t(code))}</li>`).join('')}</ul></div>`:''}<div class="trace-steps">${[['stepInput','stepInputHelp',true],['stepNeed','stepNeedHelp',!!r],['stepScope','stepScopeHelp',!early],['stepModel','stepModelHelp',reachedModel]].map(([title,help,passed],i)=>`<div class="trace-step ${!passed?'pending':''}"><span class="step-mark">${i+1}</span><div>${t(title)}<p>${t(help)}</p></div></div>`).join('')}</div><div class="trace-note">${I('info')} ${t('simulationDisclaimer')}</div></section>`}
function labView(){return `<div class="lab-layout"><section class="panel"><div class="panel-head"><div><h2>${t('scenarioTitle')}</h2><p class="panel-desc">${t('scenarioSubtitle')}</p></div><span class="page-num">10</span></div><div class="scenario-grid">${scenarios.map((k,i)=>`<button class="scenario ${state.scenario===k?'selected':''}" data-scenario="${k}" aria-pressed="${state.scenario===k}">${I(({routine:'tune',mechanical:'layers',explicit:'message',review:'shield',architecture:'branch',local_trial:'tune',borderline:'branch',critical:'target',deadline:'bolt',tiny:'clock'})[k])}<strong>${t('scenario'+scenarioKeys[k])}</strong><small>${t('scenario'+scenarioKeys[k]+'Desc')}</small></button>`).join('')}</div><div class="lab-options"><div><label class="field-label" for="environment">${t('environment')}</label>${select('environment',[['ready',t('ready')],['conflict',t('conflict')],['offline',t('offline')],['no-models',t('noModels')]],state.options.environment,t('environment'))}</div><div><label class="field-label" for="sim-minutes">${t('minMinutes')}</label><input class="model-input" type="number" id="sim-minutes" min="0" max="120" data-sim="minutes" value="${state.options.minutes??({routine:12,review:8,explicit:6,deadline:10,critical:12,tiny:1,mechanical:8,architecture:15,local_trial:10,borderline:10}[state.scenario])}"></div><div><label class="field-label" for="sim-active">${t('activeChildren')}</label><input class="model-input" id="sim-active" type="number" min="0" max="3" data-sim="active_children" value="${state.options.active_children}"></div><div><label class="field-label" for="sim-started">${t('startedChildren')}</label><input class="model-input" id="sim-started" type="number" min="0" max="6" data-sim="children_started" value="${state.options.children_started}"></div></div>${button('simulate',t('simulate'),'play','btn-primary lab-run',state.busy?'disabled':'')}</section>${trace()}</div>`}
function dateLabel(s){return new Intl.DateTimeFormat(lang==='zh'?'zh-CN':'en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(s))}
function historyView(){const rows=state.meta.history;return `<section class="panel"><div class="panel-head"><div><h2>${t('historyTitle')}</h2><p class="panel-desc">${t('subHistory')}</p></div><span class="history-count">${rows.length} ${t('backups')}</span></div><div class="history-list"><div class="history-row"><span class="history-symbol">${I('check')}</span><div><h3>${t('current')} <span class="badge">${t(state.base.enabled?'enabled':'disabled')}</span></h3><p>${t('currentDesc')} · ${state.meta.revision.slice(0,8)}</p></div></div>${rows.map(h=>`<div class="history-row"><span class="history-symbol">${I('history')}</span><div><h3>${dateLabel(h.created_at)}</h3><p>${t('snapshot')} · ${h.revision.slice(0,8)}</p></div>${button('history-load',t('loadDraft'),'refresh','btn-outline',`data-history="${E(h.id)}"`)}</div>`).join('')}</div>${!rows.length?`<div class="empty">${I('history')}<h3>${t('noHistory')}</h3><p>${t('noHistoryDesc')}</p></div>`:''}</section><div class="footer-note">${I('shield')}${t('confirmNote')}</div>`}
function render(){if(!state.base)return;const focus=document.activeElement;const focusKey=focus?.id||null;const focusData=focus?.dataset?{...focus.dataset}:{};const focusValue=focus?.tagName==='INPUT'?focus.value:null;document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.body.className=lang==='en'?'en':'';$('.skip-link').textContent=lang==='zh'?'跳转到正文':'Skip to content';const view=state.view;const page=({overview:'Overview',models:'Models',lab:'Lab',history:'History'})[view];const diffs=differences();state.dirty=!!diffs.length;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${I('branch')}</span><div><strong>Router Studio</strong><small>WORKSPACE ROUTER</small></div></div><div class="side-label">${t('manage')}</div><nav class="nav" aria-label="${t('navigation')}">${[['overview','grid'],['models','layers'],['lab','flask'],['history','history']].map(([key,icon])=>`<button class="nav-btn ${view===key?'active':''}" data-view="${key}" ${view===key?'aria-current="page"':''}>${I(icon)}${t(key)}</button>`).join('')}</nav><div class="sidebar-foot"><div class="local-card"><strong><span class="dot"></span>${t('localOnly')}</strong><p>${t('localDesc')}</p></div><div class="side-bottom"><span>v${E(state.meta.engine_version)}</span><span>MADE FOR CODEX</span></div></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb">${I('terminal')}<span>${t('workspace')}</span>${I('chevron')}<strong>${t(view)}</strong></div><div class="header-controls"><div class="language" aria-label="Language"><button data-lang="zh" class="${lang==='zh'?'active':''}" aria-label="切换为中文">中</button><button data-lang="en" class="${lang==='en'?'active':''}" aria-label="Switch to English">EN</button></div><span class="connection"><span class="dot"></span>${t('local')}</span><span class="avatar">WS</span></div></header><main id="main"><div class="page-head"><div><div class="eyebrow">ROUTING WORKSPACE <span> / 0${['overview','models','lab','history'].indexOf(view)+1}</span></div><h1>${t('page'+page)}</h1><p class="subtitle">${t('sub'+page)}</p></div><div class="head-actions"><button class="icon-button" data-action="reload" aria-label="${t('reload')}" title="${t('reload')}">${I('refresh')}</button>${button('import',t('import'),'upload','btn-ghost')}${button('export',t('export'),'download')}${button('review',t('apply'),'arrowUp','btn-primary',!state.dirty?'disabled':'')}</div></div><div class="page-content">${({overview,models:modelView,lab:labView,history:historyView})[view]()}</div></main></div><div class="save-bar ${state.dirty?'visible':''}" ${state.dirty?'':'inert aria-hidden="true"'}><div><p>${I('info')}<span data-dirty-count>${diffs.length} ${t('dirty')}</span></p><small>${t('dirtySub')}</small></div><div class="save-actions">${button('discard',t('discard'),null,'btn-ghost')}${button('review',t('apply'),'arrowUp','btn-primary')}</div></div></div><input class="file-input" type="file" id="import-file" accept="application/json,.json">`;
 const restored=focusKey?document.getElementById(focusKey):[...document.querySelectorAll('button,input,select')].find(n=>Object.keys(focusData).length&&Object.entries(focusData).every(([k,v])=>n.dataset[k]===v));if(restored&&!state.modal){if(focusValue!==null&&restored.tagName==='INPUT')restored.value=focusValue;restored.focus({preventScroll:true})}if(state.modal)renderModal();
}
function edited(){state.dirty=!!differences().length;state.result=null;render();clearTimeout(simTimer);simTimer=setTimeout(runSimulation,220)}
function rangeEdit(node){const key=node.dataset.range;state.draft[key]=Number(node.value);if(key==='max_children'&&state.draft.max_children>state.draft.max_children_per_request)state.draft.max_children_per_request=state.draft.max_children;if(key==='max_children_per_request'&&state.draft.max_children_per_request<state.draft.max_children)state.draft.max_children=state.draft.max_children_per_request;for(const k of ['max_children','max_children_per_request','minimum_reasoning_minutes','max_recovery_attempts','catalog_max_age_hours']){const output=$(`[data-output="${k}"]`);if(output)output.textContent=state.draft[k];const range=$(`[data-range="${k}"]`);if(range){range.value=state.draft[k];range.setAttribute('aria-valuetext',state.draft[k])}const stat=$(`[data-stat="${k}"]`);if(stat)stat.textContent=String(state.draft[k]).padStart(2,'0')}const changes=differences();state.dirty=!!changes.length;$('.save-bar').classList.toggle('visible',state.dirty);$('.save-bar').inert=!state.dirty;$('.save-bar').setAttribute('aria-hidden',String(!state.dirty));$('[data-dirty-count]').textContent=`${changes.length} ${t('dirty')}`;document.querySelectorAll('[data-action="review"]').forEach(b=>b.disabled=!state.dirty);}
async function runSimulation(){if(!state.base)return;const seq=++simulationSequence;const snapshot=JSON.stringify(state.draft);state.busy=true;state.result=null;render();try{const r=await api('/api/simulate',{policy:state.draft,options:{...state.options,scenario:state.scenario}});if(seq!==simulationSequence||snapshot!==JSON.stringify(state.draft))return;state.result=r;state.busy=false;render()}catch(err){if(seq!==simulationSequence)return;state.busy=false;render();toast(errorText(err))}}
async function load(){try{const data=await api('/api/state');state.meta=data;state.base=normalise(data.policy);state.draft=copy(state.base);state.connected=true;state.result=null;render();runSimulation()}catch(err){state.connected=false;$('#app').innerHTML=`<div class="error-page"><span class="brand-mark">${I('branch')}</span><h1>${t('connectTitle')}</h1><p>${errorText(err)}</p>${button('retry',t('retry'),'refresh','btn-primary')}<div class="language"><button data-lang="zh">中</button><button data-lang="en">EN</button></div></div>`}}
function renderModal(){const diffs=differences();$('#modal-root').innerHTML=`<div class="modal-scrim" data-modal-scrim><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${t('confirmTitle')}</h2><p>${t('confirmDesc')}</p></div><button class="icon-button" data-action="cancel" aria-label="${t('close')}">${I('close')}</button></div><div class="modal-body"><div class="modal-source">${E(state.meta.target)}</div><div class="diff-row"><span>${t('policy')}</span><span>${t('before')}</span><span>${t('after')}</span></div>${diffs.map(d=>`<div class="diff-row"><span>${E(d.label)}</span><span class="before">${E(d.before)}</span><span class="after">${E(d.after)}</span></div>`).join('')}<p class="modal-note">${t('confirmNote')}</p></div><div class="modal-actions">${button('cancel',t('cancel'),null,'btn-ghost')}${button('save',t('confirmSave'),'check','btn-primary')}</div></section></div>`;requestAnimationFrame(()=>$('#modal-root [data-action="cancel"]')?.focus())}
function closeModal(){state.modal=false;$('#modal-root').innerHTML='';$('[data-action="review"]')?.focus()}
async function review(){if(!differences().length){toast(t('noChanges'));return}try{await api('/api/validate',{policy:state.draft});state.modal=true;renderModal()}catch(err){toast(errorText(err))}}
async function save(){const b=$('[data-action="save"]');if(b)b.disabled=true;try{const data=await api('/api/save',{policy:state.draft,revision:state.meta.revision});state.meta=data;state.base=normalise(data.policy);state.draft=copy(state.base);closeModal();render();toast(t('changed'))}catch(err){if(b)b.disabled=false;toast(errorText(err))}}
function exportPolicy(){const blob=new Blob([JSON.stringify(state.draft,null,2)+'\n'],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='workspace-router-policy.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('exported'))}
function preset(name){const p=state.meta.presets?.[name];if(!p)return;state.draft=normalise(p);edited();toast(t('presetLoaded'))}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.lang){lang=b.dataset.lang;localStorage.setItem('router-studio-language',lang);if(state.base)render();else load();return}
 if(b.dataset.view){state.view=b.dataset.view;render();window.scrollTo({top:0,behavior:'smooth'});return}
 if(b.dataset.toggle){const key=b.dataset.toggle;if(key==='enabled')state.draft.enabled=!state.draft.enabled;else{const k=key.split('.')[1];state.draft.triggers[k]=!state.draft.triggers[k]}edited();return}
 if(b.dataset.preset){preset(b.dataset.preset);return}
 if(b.dataset.scenario){state.scenario=b.dataset.scenario;delete state.options.minutes;runSimulation();return}
 if(b.dataset.up||b.dataset.remove){const [lane,index]=(b.dataset.up||b.dataset.remove).split(':');const i=Number(index),rows=state.draft.lanes[lane];if(b.dataset.up&&i>0)[rows[i-1],rows[i]]=[rows[i],rows[i-1]];else if(b.dataset.remove&&rows.length>1)rows.splice(i,1);edited();return}
 if(b.dataset.add){const rows=state.draft.lanes[b.dataset.add];const candidates=state.meta.models;const model=candidates.find(m=>!rows.some(([x,f])=>x===m&&f==='medium'))||'custom-model';rows.push([model,'medium']);edited();return}
 switch(b.dataset.action){case'restore-defaults':loadRecommended();break;case'review':review();break;case'save':save();break;case'cancel':closeModal();break;case'export':exportPolicy();break;case'import':$('#import-file').click();break;case'discard':state.draft=copy(state.base);edited();toast(t('discarded'));break;case'go-lab':state.view='lab';render();window.scrollTo({top:0,behavior:'smooth'});break;case'simulate':runSimulation();break;case'retry':load();break;case'reload':if(!state.dirty||window.confirm(t('draftWillDiscard'))){await load();toast(t('loaded'))}break;case'history-load':{const h=state.meta.history.find(h=>h.id===b.dataset.history);if(h){state.draft=normalise(h.policy);state.view='overview';edited();toast(t('historyHint'));window.scrollTo({top:0,behavior:'smooth'})}break;}}
});
document.addEventListener('input',ev=>{if(ev.target.dataset.range)rangeEdit(ev.target)});
document.addEventListener('change',async ev=>{const n=ev.target;
 if(n.dataset.range){edited();return}
 if(n.dataset.model||n.dataset.effort){const [lane,index]=(n.dataset.model||n.dataset.effort).split(':');state.draft.lanes[lane][Number(index)][n.dataset.model?0:1]=n.value.trim();edited();return}
 if(n.dataset.select==='quick-scenario'){state.scenario=n.value;delete state.options.minutes;runSimulation();return}
 if(n.dataset.select==='environment'){state.options.environment=n.value;runSimulation();return}
 if(n.dataset.sim){const key=n.dataset.sim;state.options[key]=Number(n.value);if(key==='active_children')state.options.children_started=Math.max(state.options.children_started,state.options.active_children);runSimulation();return}
 if(n.id==='import-file'){const f=n.files[0];if(!f)return;if(f.size>65536){toast(t('invalidFile'));return}try{const p=JSON.parse(await f.text());await api('/api/validate',{policy:p});state.draft=normalise(p);edited();toast(t('imported'))}catch(err){toast(err.status?errorText(err):t('invalidFile'))}finally{n.value=''}}
});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&state.modal){closeModal();return}if(ev.key==='Tab'&&state.modal){const elements=[...$('#modal-root').querySelectorAll('button:not(:disabled)')];const first=elements[0],last=elements.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus()}}});
window.addEventListener('beforeunload',ev=>{if(state.dirty){ev.preventDefault();ev.returnValue=''}});
$('#app').innerHTML=`<div class="loading"><span class="spinner"></span>Router Studio</div>`;
load();
